local InstanceManager = require(script.Parent.Parent.InstancePathManager)
local ServiceDescriptorImplementationTypeResolver = require(script.Parent.ServiceDescriptorImplementationTypeResolver)

type ImplementationType = string | ModuleScript

local ActivatorUtilities = {}

function ActivatorUtilities.CreateInstance(serviceProvider: IServiceProvider, targetType: ImplementationType, ...)
	local luaTypeProvider: ILuaTypeProvider = serviceProvider:GetRequiredService("ILuaTypeProvider")

	local type = type(targetType)
	assert(
		type == "string" or typeof(targetType) == "Instance" and targetType:IsA("ModuleScript"),
		"targetType must be a string or ModuleScript"
	)

	if type ~= "string" then
		targetType = InstanceManager.GetPathAndCache(targetType)
	end

	local args = { ... }

	return ServiceDescriptorImplementationTypeResolver.ResolveFromImplementationTypeWithArgs(
		serviceProvider,
		targetType,
		targetType,
		targetType,
		{},
		luaTypeProvider,
		unpack(args)
	)
end

return ActivatorUtilities
